query:
-- pre: DROP TABLE IF EXISTS cov_hll;
-- pre: CREATE TABLE cov_hll (id int, g int, k int, u uuid) WITH (autovacuum_enabled = off);
-- pre: INSERT INTO cov_hll SELECT i, i % 7, (i * 7919) % 20000, md5(i::text)::uuid FROM generate_series(1, 60000) i;
-- pre: CREATE INDEX cov_hll_col ON cov_hll USING sift_col (id, g, k, u) WITH (hll_columns = 'k, u');
-- pre: VACUUM (FREEZE, ANALYZE) cov_hll;
SELECT sift.approx_count_distinct(k), sift.approx_count_distinct(u) FROM cov_hll

-- pre: DROP TABLE IF EXISTS cv_pt;
-- pre: CREATE TABLE cv_pt (id int, p point, t tsvector, j json, x xml);
-- pre: INSERT INTO cv_pt SELECT i, CASE WHEN i % 3 = 0 THEN NULL ELSE point(i, i) END, to_tsvector('simple', 'w' || i), json_build_object('i', i), ('<a>' || i || '</a>')::xml FROM generate_series(1, 100) i;
-- pre: CREATE INDEX cv_x ON cv_pt USING sift_col (id, p, t, j, x);
SELECT count(p), count(t), count(j), count(x) FROM cv_pt WHERE id > 10 AND p IS NOT NULL

-- pre: DROP TABLE IF EXISTS cov_kc;
-- pre: CREATE TABLE cov_kc (id int, k int, g int, v int) WITH (autovacuum_enabled = off);
-- pre: INSERT INTO cov_kc SELECT i, (i * 7919) % 5000, i % 7, i % 100 FROM generate_series(1, 20000) i;
-- pre: CREATE INDEX cov_kc_col ON cov_kc USING sift_col (id, k, g, v) WITH (key_order = 'k');
-- pre: VACUUM (FREEZE, ANALYZE) cov_kc;
SELECT g, count(*), sum(v) FROM cov_kc WHERE k BETWEEN 100 AND 140 GROUP BY g

-- pre: DROP TABLE IF EXISTS cov_pk;
-- pre: CREATE TABLE cov_pk (id int, k int, v int, pad text DEFAULT repeat('x', 400)) WITH (autovacuum_enabled = off);
-- pre: ALTER TABLE cov_pk ALTER COLUMN pad SET STORAGE PLAIN;
-- pre: INSERT INTO cov_pk (id, k, v) SELECT i, (i * 7919) % 9000, i % 100 FROM generate_series(1, 30000) i;
-- pre: CREATE INDEX cov_pk_col ON cov_pk USING sift_col (id, k, v) WITH (point_tid_columns = 'k');
-- pre: VACUUM (FREEZE, ANALYZE) cov_pk;
SELECT count(*), sum(v) FROM cov_pk WHERE k IN (17, 4242, 3, 8999, 123456)

-- pre: DROP TABLE IF EXISTS cov_ev;
-- pre: CREATE TABLE cov_ev (id int PRIMARY KEY, grp int NOT NULL, ts int, amount int NOT NULL) WITH (autovacuum_enabled = off);
-- pre: INSERT INTO cov_ev SELECT i, i % 37, (i * 31) % 1000, i % 11 FROM generate_series(1, 5000) i;
-- pre: CREATE INDEX cov_ev_col ON cov_ev USING sift_col (id, grp, ts, amount);
-- pre: VACUUM (FREEZE, ANALYZE) cov_ev;
-- guc: seq_page_cost = 1000
-- guc: random_page_cost = 1000
SELECT grp, id, rn FROM (SELECT grp, id, ts, row_number() OVER (PARTITION BY grp ORDER BY ts, id) rn FROM cov_ev) s WHERE rn <= 3

-- pre: DO $f$ BEGIN IF current_setting('sift.test_create_format1', true) IS NOT NULL THEN PERFORM set_config('sift.test_create_format1', 'off', false); END IF; END $f$;
-- pre: CREATE OR REPLACE FUNCTION pg_temp.granules(q text) RETURNS int LANGUAGE plpgsql AS $f$ DECLARE l text; n int := 0; BEGIN FOR l IN EXECUTE 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) ' || q LOOP n := n + coalesce(substring(l from 'preagg=(\d+)')::int, 0); END LOOP; RETURN n; END $f$;
-- pre: CREATE OR REPLACE FUNCTION pg_temp.same(q text) RETURNS boolean LANGUAGE plpgsql AS $f$ DECLARE a text; b text; BEGIN PERFORM set_config('sift.enable_agg', 'on', true); EXECUTE 'SELECT string_agg(t::text, chr(10) ORDER BY t::text) FROM (' || q || ') t' INTO a; PERFORM set_config('sift.enable_agg', 'off', true); EXECUTE 'SELECT string_agg(t::text, chr(10) ORDER BY t::text) FROM (' || q || ') t' INTO b; PERFORM set_config('sift.enable_agg', 'on', true); RETURN a IS NOT DISTINCT FROM b; END $f$;
-- pre: DROP TABLE IF EXISTS cv_p2;
-- pre: CREATE TABLE cv_p2 AS SELECT i AS id, i % 5 AS a, 'b' || (i % 3) AS b, i % 7 AS c, i % 40 AS u, ((i % 800) * 0.25)::float8 AS f, encode(sha256((i::text || 'a')::bytea), 'base64') || encode(sha256((i::text || 'b')::bytea), 'base64') || encode(sha256((i::text || 'c')::bytea), 'base64') AS pad FROM generate_series(1, 60000) i;
-- pre: CREATE INDEX cv_p2_col ON cv_p2 USING sift_col (id, a, b, c, u, f, pad);
-- pre: VACUUM (FREEZE, ANALYZE) cv_p2;
SELECT pg_temp.granules('SELECT a, b, c, count(*), sum(f), min(f), max(f) FROM cv_p2 GROUP BY a, b, c') > 0 AND pg_temp.granules('SELECT b, count(*), count(DISTINCT u) FROM cv_p2 GROUP BY b') > 0 AND pg_temp.granules('SELECT b, count(*), sum(u) FROM cv_p2 WHERE a = 2 AND c > 1 GROUP BY b') > 0 AND pg_temp.same('SELECT a, b, c, count(*), sum(f), min(f), max(f) FROM cv_p2 GROUP BY a, b, c') AND pg_temp.same('SELECT b, count(*), count(DISTINCT u) FROM cv_p2 GROUP BY b') AND pg_temp.same('SELECT b, count(*), sum(u) FROM cv_p2 WHERE a = 2 AND c > 1 GROUP BY b') AND pg_temp.same('SELECT a, count(*) FROM cv_p2 WHERE u = 3 GROUP BY a')

-- pre: DO $f$ BEGIN IF current_setting('sift.test_create_format1', true) IS NOT NULL THEN PERFORM set_config('sift.test_create_format1', 'off', false); END IF; END $f$;
-- pre: CREATE OR REPLACE FUNCTION pg_temp.granules(q text) RETURNS int LANGUAGE plpgsql AS $f$ DECLARE l text; n int := 0; BEGIN FOR l IN EXECUTE 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) ' || q LOOP n := n + coalesce(substring(l from 'preagg=(\d+)')::int, 0); END LOOP; RETURN n; END $f$;
-- pre: CREATE OR REPLACE FUNCTION pg_temp.same(q text) RETURNS boolean LANGUAGE plpgsql AS $f$ DECLARE a text; b text; BEGIN PERFORM set_config('sift.enable_agg', 'on', true); EXECUTE 'SELECT string_agg(t::text, chr(10) ORDER BY t::text) FROM (' || q || ') t' INTO a; PERFORM set_config('sift.enable_agg', 'off', true); EXECUTE 'SELECT string_agg(t::text, chr(10) ORDER BY t::text) FROM (' || q || ') t' INTO b; PERFORM set_config('sift.enable_agg', 'on', true); RETURN a IS NOT DISTINCT FROM b; END $f$;
-- pre: DROP TABLE IF EXISTS cv_p6;
-- pre: CREATE TABLE cv_p6 AS SELECT i AS id, i % 7 AS g, i AS v, encode(sha256((i::text || 'a')::bytea), 'base64') || encode(sha256((i::text || 'b')::bytea), 'base64') || encode(sha256((i::text || 'c')::bytea), 'base64') AS pad FROM generate_series(1, 60000) i;
-- pre: CREATE INDEX cv_p6_col ON cv_p6 USING sift_col (id, g, v, pad) WITH (key_order = 'id');
-- pre: VACUUM (FREEZE, ANALYZE) cv_p6;
-- pre: CREATE TEMP TABLE cv_p6_obs AS SELECT 'clean'::text AS s, pg_temp.granules('SELECT g, count(*), sum(v) FROM cv_p6 GROUP BY g') AS n;
-- pre: DELETE FROM cv_p6 WHERE id > 50000 AND id % 2 = 0;
-- pre: INSERT INTO cv_p6_obs SELECT 'churn', pg_temp.granules('SELECT g, count(*), sum(v) FROM cv_p6 GROUP BY g');
-- pre: VACUUM cv_p6;
-- pre: INSERT INTO cv_p6_obs SELECT 'vacuum', pg_temp.granules('SELECT g, count(*), sum(v) FROM cv_p6 GROUP BY g');
SELECT (SELECT n FROM cv_p6_obs WHERE s = 'clean') > 0 AND (SELECT n FROM cv_p6_obs WHERE s = 'churn') > 0 AND (SELECT n FROM cv_p6_obs WHERE s = 'churn') < (SELECT n FROM cv_p6_obs WHERE s = 'clean') AND (SELECT n FROM cv_p6_obs WHERE s = 'vacuum') > 0 AND pg_temp.same('SELECT g, count(*), sum(v), min(v), max(v) FROM cv_p6 GROUP BY g')

-- pre: DO $f$ BEGIN IF current_setting('sift.test_create_format1', true) IS NOT NULL THEN PERFORM set_config('sift.test_create_format1', 'off', false); END IF; END $f$;
-- pre: CREATE OR REPLACE FUNCTION pg_temp.granules(q text) RETURNS int LANGUAGE plpgsql AS $f$ DECLARE l text; n int := 0; BEGIN PERFORM set_config('seq_page_cost', '10000', true), set_config('random_page_cost', '10000', true), set_config('sift.enable_agg', 'on', true); FOR l IN EXECUTE 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) ' || q LOOP n := n + coalesce(substring(l from 'preagg=(\d+)')::int, 0); END LOOP; RETURN n; END $f$;
-- pre: CREATE OR REPLACE FUNCTION pg_temp.same(q text) RETURNS boolean LANGUAGE plpgsql AS $f$ DECLARE a text; b text; BEGIN PERFORM set_config('sift.enable_agg', 'on', true); EXECUTE 'SELECT string_agg(t::text, chr(10) ORDER BY t::text) FROM (' || q || ') t' INTO a; PERFORM set_config('sift.enable_agg', 'off', true); EXECUTE 'SELECT string_agg(t::text, chr(10) ORDER BY t::text) FROM (' || q || ') t' INTO b; PERFORM set_config('sift.enable_agg', 'on', true); RETURN a IS NOT DISTINCT FROM b; END $f$;
-- pre: DROP TABLE IF EXISTS cv_pt;
-- pre: CREATE TABLE cv_pt (id int, g int, v int) USING sift_table;
-- pre: INSERT INTO cv_pt SELECT i, i % 7, i FROM generate_series(1, 5000) i;
-- pre: SELECT sift.table_maintain('cv_pt');
-- pre: VACUUM (FREEZE, ANALYZE) cv_pt;
-- pre: CREATE TEMP TABLE cv_pt_obs AS SELECT 'clean'::text AS s, pg_temp.granules('SELECT g, count(*), sum(v) FROM cv_pt GROUP BY g') AS n;
-- pre: DELETE FROM cv_pt WHERE id % 3 = 0;
-- pre: INSERT INTO cv_pt_obs SELECT 'churn', pg_temp.granules('SELECT g, count(*), sum(v) FROM cv_pt GROUP BY g');
SELECT (SELECT n FROM cv_pt_obs WHERE s = 'clean') > 0 AND (SELECT n FROM cv_pt_obs WHERE s = 'churn') = 0 AND pg_temp.same('SELECT g, count(*), sum(v) FROM cv_pt GROUP BY g')

-- pre: DROP TABLE IF EXISTS cov_cal;
-- pre: CREATE TABLE cov_cal (id int, d date, doc jsonb, v int) WITH (autovacuum_enabled = off);
-- pre: INSERT INTO cov_cal SELECT i, date '2024-01-01' + i % 365, jsonb_build_object('a', i % 5), i % 100 FROM generate_series(1, 20000) i;
-- pre: CREATE INDEX cov_cal_col ON cov_cal USING sift_col (id, d, doc, v) WITH (paths = 'doc.a int4', calendar_columns = 'all');
-- pre: VACUUM (FREEZE, ANALYZE) cov_cal;
SELECT date_trunc('month', d) m, count(*), sum(v) FROM cov_cal WHERE d >= date '2024-03-15' AND d < date '2024-09-01' GROUP BY 1

-- pre: DO $f$ BEGIN IF current_setting('sift.test_create_format1', true) IS NOT NULL THEN PERFORM set_config('sift.test_create_format1', 'off', false); END IF; END $f$;
-- pre: CREATE OR REPLACE FUNCTION pg_temp.granules(q text) RETURNS int LANGUAGE plpgsql AS $f$ DECLARE l text; n int := 0; BEGIN PERFORM set_config('seq_page_cost', '10000', true), set_config('random_page_cost', '10000', true), set_config('sift.enable_agg', 'on', true); FOR l IN EXECUTE 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF) ' || q LOOP n := n + coalesce(substring(l from 'preagg=(\d+)')::int, 0); END LOOP; RETURN n; END $f$;
-- pre: DROP TABLE IF EXISTS cov_ex;
-- pre: CREATE TABLE cov_ex (id int, kind int, val bigint, stamp timestamptz, pad text) WITH (autovacuum_enabled = off);
-- pre: ALTER TABLE cov_ex ALTER COLUMN pad SET STORAGE PLAIN;
-- pre: INSERT INTO cov_ex SELECT g, g % 6, (g % 997) * 3 - 1000, CASE WHEN g % 60 = 0 THEN timestamptz '2025-06-01 00:00:00+00' + g * interval '1 second' END, (SELECT string_agg(md5(g::text || s::text), '') FROM generate_series(1, 10) s) FROM generate_series(1, 24000) g;
-- pre: CREATE INDEX cov_ex_col ON cov_ex USING sift_col (id, kind, val, stamp);
-- pre: VACUUM (FREEZE, ANALYZE, DISABLE_PAGE_SKIPPING) cov_ex;
SELECT pg_temp.granules('SELECT kind, count(*), sum(val) FROM cov_ex WHERE stamp IS NULL GROUP BY kind') > 0

-- pre: DELETE FROM cv_maint WHERE id % 3 = 0;
-- pre: VACUUM cv_maint;
-- pre: INSERT INTO cv_maint SELECT 10000 + i, i % 5, i FROM generate_series(1, 700) i;
-- pre: UPDATE cv_maint SET v = v + 1 WHERE id % 5 = 0;
-- pre: SELECT sift.col_promote('cv_maint_col'), sift.col_merge('cv_maint_col');
-- pre: REINDEX INDEX cv_maint_col;
-- pre: DELETE FROM cv_maint WHERE id > 10000 AND id % 2 = 0;
-- pre: VACUUM cv_maint;
-- pre: INSERT INTO cv_maint SELECT 20000 + i, i % 5, i FROM generate_series(1, 300) i;
SELECT coverage.same('SELECT grp, count(*), sum(v), max(id) FROM cv_maint GROUP BY grp')

-- pre: DO $$ BEGIN IF current_setting('sift.test_create_format1', true) IS NOT NULL THEN PERFORM set_config('sift.test_create_format1', 'off', false); END IF; END $$;
-- pre: CREATE TABLE cv_s16 (id int PRIMARY KEY, tenant int NOT NULL, body text NOT NULL) USING sift_table;
-- pre: INSERT INTO cv_s16 SELECT i, i % 40, CASE WHEN i % 25 = 0 THEN 'damaged parcel' ELSE 'fine' END FROM generate_series(1, 2000) i;
-- pre: CREATE INDEX cv_s16_text ON cv_s16 USING sift (body);
-- pre: ANALYZE cv_s16;
-- guc: enable_seqscan = off
-- guc: enable_bitmapscan = off
SELECT id FROM cv_s16 WHERE body @@> 'damaged' OR tenant = 5

-- pre: DROP TABLE IF EXISTS cv_u;
-- pre: CREATE TABLE cv_u (id int, a int, b text);
-- pre: DO $$ BEGIN IF current_setting('sift.test_create_format1', true) IS NOT NULL THEN PERFORM set_config('sift.test_create_format1', 'off', false); END IF; END $$;
-- pre: CREATE UNIQUE INDEX cv_u_x ON cv_u USING sift_col (id) INCLUDE (a, b);
SELECT indisunique AND indnatts = 3 AND indnkeyatts = 1 FROM pg_index WHERE indexrelid = 'cv_u_x'::regclass

-- pre: CREATE TABLE cv_l06a (id int, v int) USING sift_table;
-- pre: COPY cv_l06a FROM PROGRAM 'seq 1 1500 | sed -E "s/(.*)/\1,\1/"' (FORMAT csv);
-- pre: COPY cv_l06a TO PROGRAM 'wc -l >/dev/null' (FORMAT csv);
-- pre: CREATE TABLE cv_l06b (id int, v int) USING sift_table;
-- pre: INSERT INTO cv_l06b SELECT i, i * 2 FROM generate_series(1, 1500) i;
-- pre: CREATE TABLE cv_l06c USING sift_table AS SELECT i AS id, i * 3 AS v FROM generate_series(1, 1500) i;
-- pre: CREATE TABLE cv_l06d AS SELECT i AS id, i * 4 AS v FROM generate_series(1, 1500) i;
-- pre: ALTER TABLE cv_l06d SET ACCESS METHOD sift_table;
-- pre: VACUUM cv_l06a, cv_l06b, cv_l06c, cv_l06d;
SELECT bool_and(coverage.same(format('SELECT id %% 7, count(*), sum(v) FROM %s GROUP BY 1', t))) FROM unnest(ARRAY['cv_l06a', 'cv_l06b', 'cv_l06c', 'cv_l06d']) t

-- pre: CREATE TABLE cv_l08 (id int PRIMARY KEY, g int, v int) USING sift_table;
-- pre: INSERT INTO cv_l08 SELECT i, i % 7, i FROM generate_series(1, 2000) i;
-- pre: UPDATE cv_l08 SET v = v + 1 WHERE id % 5 = 0;
-- pre: DELETE FROM cv_l08 WHERE id % 11 = 0;
-- pre: INSERT INTO cv_l08 SELECT i, 1, i FROM generate_series(1, 20) i ON CONFLICT (id) DO UPDATE SET v = excluded.v + 100;
-- pre: BEGIN;
-- pre: SELECT id FROM cv_l08 WHERE id < 5 FOR SHARE;
-- pre: SAVEPOINT s1;
-- pre: UPDATE cv_l08 SET v = -1 WHERE id < 3;
-- pre: ROLLBACK TO s1;
-- pre: SELECT id FROM cv_l08 WHERE id BETWEEN 10 AND 12 FOR UPDATE;
-- pre: COMMIT;
-- pre: CREATE FUNCTION cv_l08_trg() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.v := NEW.v + 1; RETURN NEW; END $$;
-- pre: CREATE TRIGGER cv_l08_t BEFORE UPDATE ON cv_l08 FOR EACH ROW EXECUTE FUNCTION cv_l08_trg();
-- pre: UPDATE cv_l08 SET v = v WHERE id % 13 = 0;
-- pre: CREATE INDEX cv_l08_v ON cv_l08 (v);
-- pre: VACUUM FULL cv_l08;
-- pre: CLUSTER cv_l08 USING cv_l08_v;
SELECT coverage.same('SELECT g, count(*), sum(v), min(v) FROM cv_l08 GROUP BY g')

-- pre: CREATE TABLE cv_l09 (id int, v int) USING sift_table;
-- pre: BEGIN;
-- pre: INSERT INTO cv_l09 SELECT i, i FROM generate_series(1, 3) i;
-- pre: CREATE TABLE cv_l09x AS SELECT pg_current_xact_id()::xid AS x;
-- pre: COMMIT;
SELECT bool_and(xmin = (SELECT x FROM cv_l09x)) AND bool_and(cmin::text = '0') AND count(*) FILTER (WHERE xmax::text <> '0') = 0 FROM cv_l09

-- pre: DROP TABLE IF EXISTS cov_items;
-- pre: DROP TABLE IF EXISTS cov_owners;
-- pre: CREATE TABLE cov_owners (id int PRIMARY KEY, k int) WITH (autovacuum_enabled = off);
-- pre: INSERT INTO cov_owners SELECT i, CASE WHEN i % 13 = 0 THEN NULL ELSE i % 1500 END FROM generate_series(1, 2000) i;
-- pre: CREATE TABLE cov_items (id int PRIMARY KEY, set_id int, cat int, amt int) WITH (autovacuum_enabled = off);
-- pre: INSERT INTO cov_items SELECT i, CASE WHEN i % 17 = 0 THEN NULL ELSE i % 1200 END, i % 9, CASE WHEN i % 23 = 0 THEN NULL ELSE (i * 7) % 100 END FROM generate_series(1, 30000) i;
-- pre: CREATE INDEX cov_items_col ON cov_items USING sift_col (id, set_id, cat, amt);
-- pre: CREATE INDEX cov_items_owner ON cov_items (set_id);
-- pre: VACUUM (FREEZE, ANALYZE) cov_owners;
-- pre: VACUUM (FREEZE, ANALYZE) cov_items;
SELECT o.id, s.t, s.c FROM cov_owners o, LATERAL (SELECT sum(i.amt) t, count(*) c FROM cov_items i WHERE i.set_id = o.k) s

-- pre: DROP TABLE IF EXISTS cov_items;
-- pre: DROP TABLE IF EXISTS cov_owners;
-- pre: CREATE TABLE cov_owners (id int PRIMARY KEY, k int) WITH (autovacuum_enabled = off);
-- pre: INSERT INTO cov_owners SELECT i, CASE WHEN i % 13 = 0 THEN NULL ELSE i % 1500 END FROM generate_series(1, 2000) i;
-- pre: CREATE TABLE cov_items (id int PRIMARY KEY, set_id int, cat int, amt int) WITH (autovacuum_enabled = off);
-- pre: INSERT INTO cov_items SELECT i, CASE WHEN i % 17 = 0 THEN NULL ELSE i % 1200 END, i % 9, CASE WHEN i % 23 = 0 THEN NULL ELSE (i * 7) % 100 END FROM generate_series(1, 30000) i;
-- pre: CREATE INDEX cov_items_col ON cov_items USING sift_col (id, set_id, cat, amt);
-- pre: CREATE INDEX cov_items_owner ON cov_items (set_id);
-- pre: VACUUM (FREEZE, ANALYZE) cov_owners;
-- pre: VACUUM (FREEZE, ANALYZE) cov_items;
SELECT o.id, s.cat, s.t FROM cov_owners o LEFT JOIN LATERAL (SELECT i.cat, sum(i.amt) t FROM cov_items i WHERE i.set_id = o.k GROUP BY i.cat) s ON true
